let LocationKey = runtime.inputs().LK




function hashString(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    hash = (hash << 5) - hash + str.charCodeAt(i);
    hash |= 0;
  }
  return Math.abs(hash);
}

function seededRandom(seed) {
  const x = Math.sin(seed++) * 10000;
  return x - Math.floor(x);
}

function getMockEnergyData(location) {
  const seed = hashString(location);
  const currentYear = 2025;
  const lastFiveYears = [];

  let totalEnergy = 0;
  let renewablePercentage2025 = 0;

  // Generate renewable percentages for last 5 years
  for (let i = 0; i < 5; i++) {
    const year = currentYear - (5 - i);
    const percentage = Math.floor(10 + seededRandom(seed + i) * 40); // 10% - 50%
    lastFiveYears.push({
      year,
      renewablePercentage: percentage
    });
    if (year === 2024) renewablePercentage2025 = percentage;
  }

  // Simulate total energy consumption for current year
  totalEnergy = Math.floor(1000 + seededRandom(seed + 99) * 500); // 1000 - 1500 kWh

  // Calculate current year renewable split
  const renewables_kWh = Math.round((renewablePercentage2025 / 100) * totalEnergy);
  const grid_kWh = totalEnergy - renewables_kWh;

  const donutChart = {
    data: [
      {
        source: "Renewables",
        percentage: renewablePercentage2025,
        energy_kWh: renewables_kWh
      },
      {
        source: "Grid Power",
        percentage: 100 - renewablePercentage2025,
        energy_kWh: grid_kWh
      }
    ]
  };

  return {
    location,
    currentYear,
    donutChart,
    lastFiveYears
  };
}

