function getLocationType(locationKey) {
  if (typeof locationKey === "string") locationKey = locationKey.toUpperCase();
  if (String(locationKey).startsWith("S") || locationKey < 20000) return "Site";
  if (String(locationKey).startsWith("B") || locationKey < 30000) return "Building";
  if (String(locationKey).startsWith("F") || locationKey >= 30000) return "Floor";
  return "Unknown";
}

function generateHourlyData(seed, baseConsumption, baseCostPerKWh) {
  const hourly = [];
  let totalConsumption = 0;
  let totalCost = 0;

  for (let i = 0; i <= 10; i++) {
    const hour = i.toString().padStart(2, "0") + ":00";
    const variation = seededRandom(seed + i) * 0.2 + 0.9;
    const consumption = Math.round(baseConsumption * variation);
    const cost = +(consumption * baseCostPerKWh).toFixed(2);

    hourly.push({ hour, consumption, cost });
    totalConsumption += consumption;
    totalCost += cost;
  }

  return {
    hourly,
    totalConsumption,
    totalCost: +totalCost.toFixed(2)
  };
}

function getMockEnergyUsageData(locationKey) {
  const seed = hashString(locationKey.toString());
  const locationType = getLocationType(locationKey);

  const baseConfig = {
    Site: { consumption: 50, costPerKWh: 0.25 },
    Building: { consumption: 25, costPerKWh: 0.26 },
    Floor: { consumption: 8, costPerKWh: 0.27 }
  };

  const { consumption, costPerKWh } = baseConfig[locationType] || baseConfig["Floor"];

  // Generate current and previous data
  const current = generateHourlyData(seed + 10, consumption, costPerKWh);
  const previous = generateHourlyData(seed + 20, consumption * 1.05, costPerKWh * 1.02);

  const date = "2024-06-10";
  const prevDate = "2024-06-09";

  current.from = `${date}T00:00:00Z`;
  current.to = `${date}T10:00:00Z`;
  previous.from = `${prevDate}T00:00:00Z`;
  previous.to = `${prevDate}T10:00:00Z`;

  // Add a spike alert at some hour in current day
  const spikeHourIndex = Math.floor(seededRandom(seed + 50) * 11);
  const spikeHour = current.hourly[spikeHourIndex];
  const spikeValue = spikeHour.consumption * 3;

  const alerts = [
    {
      type: "spike",
      timestamp: `${date}T${spikeHour.hour}:15:00Z`,
      description: "Unusual spike detected in energy usage"
    }
  ];

  const spikesLast24Hours = [
    {
      timestamp: `${date}T0${(spikeHourIndex + 2) % 10}:30:00Z`,
      value: Math.round(seededRandom(seed + 60) * 200 + 50)
    },
    {
      timestamp: `${prevDate}T2${(spikeHourIndex + 3) % 10}:45:00Z`,
      value: Math.round(seededRandom(seed + 70) * 200 + 50)
    }
  ];

  return {
    locationKey,
    locationType,
    unit: "kWh",
    costUnit: "SGD",
    current,
    previous,
    alerts,
    spikesLast24Hours
  };
}

